package com.gomgomapps.math.core;
import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class FractionDecimalComparisonTest {
 @Test public void allOriginalEquivalencesAndNeighboursIgnoreKeys(){int count=0;for(int d:List.of(2,4,5,10,100))for(int n=0;n<=d;n++)for(int offset=-1;offset<=1;offset++){int h=100*n/d+offset;if(h<0||h>100)continue;for(boolean left:new boolean[]{false,true}){Question q=FractionDecimalComparison.make(n,d,h,left);q.answers[0]="poison";q.expression="poison";int cmp=Integer.compare(n*100,h*d)*(left?1:-1);String expected=cmp<0?"<":cmp>0?">":"=";assertTrue(new Checker().check(q,List.of(),List.of(expected)).correct());assertFalse(new Checker().check(q,List.of(),List.of(expected.equals("=")?"<":"=")).correct());HelpPlan help=HelpPlan.forQuestion(q);assertEquals(5,help.size());assertFalse(help.canTransfer());assertTrue(help.step(4).accepts(expected));count++;}}assertEquals(736,count);}
 @Test public void bothOrdersZeroWholeAndMalformedStatements(){for(boolean left:new boolean[]{false,true}){Question q=FractionDecimalComparison.make(1,4,25,left);assertTrue(new Checker().check(q,List.of(),List.of("=")).correct());assertNull(FractionDecimalComparison.read(new Question(q.skillId,q.prompt.replace("1/4","1/0"),"","=")));}assertEquals(Checker.Status.INPUT_NEEDED,new Checker().check(FractionDecimalComparison.make(1,2,50,true),List.of(),List.of("same")).status);}
 @Test public void normalNaSixHasFreshOrdersDenominatorsAndAllSigns(){var p=GlobalCurriculum.packs("NA").stream().filter(x->x.id.equals("na-nied-primary-2024-v1")).findFirst().orElseThrow();assertTrue(p.inGrade(FractionDecimalComparison.ID,6));var l=GlobalCurriculum.limits(p.id,FractionDecimalComparison.ID,6);Generator g=new Generator(new Random(288));List<String> recent=new ArrayList<>();Set<Integer> den=new HashSet<>();Set<String> signs=new HashSet<>();Set<Boolean> orders=new HashSet<>();for(int i=0;i<150;i++){Question q=g.next(FractionDecimalComparison.ID,recent,false,l);assertFalse(recent.contains(q.signature()));recent.add(q.signature());var v=FractionDecimalComparison.read(q);assertNotNull(v);den.add(v.denominator());orders.add(v.fractionLeft());signs.add(FractionDecimalComparison.sign(v));assertTrue(l.allows(q));assertTrue(new Checker().check(q,List.of(),List.of(FractionDecimalComparison.sign(v))).correct());}assertEquals(Set.of(2,4,5,10,100),den);assertEquals(Set.of(true,false),orders);assertEquals(Set.of("<","=",">"),signs);}
}
